const output = $('AI Agent').first().json.output;
const phone = $('Webhook').first().json.body.phone;

// Limpa markdown
const clean = output.replace(/```json|```/g, '').trim();

let parsed;

try {
  parsed = JSON.parse(clean);
} catch (error) {
  parsed = {
    resposta: 'Desculpe, não consegui entender sua mensagem 😅',
    intencao: 'outro',
    valor: 0,
    descricao: ''
  };
}

// Detecta categoria para despesas
function detectarCategoria(descricao) {
  if (!descricao) return 'outro';

  const d = descricao.toLowerCase();

  if (/combustiv|gasolina|etanol|diesel|posto/.test(d))
    return 'combustivel';

  if (/oleo|pneu|freio|revisao|mecanico|oficina|manutencao/.test(d))
    return 'manutencao';

  if (/crlv|ipva|seguro|cnh|licenci|vistoria/.test(d))
    return 'documentacao';

  if (/lavagem|limpeza/.test(d))
    return 'lavagem';

  return 'outro';
}

// Detecta tipo de manutenção
function detectarTipoManutencao(descricao) {
  if (!descricao) return 'outro';

  const d = descricao
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

  if (/oleo/.test(d)) return 'oleo';
  if (/pneu/.test(d)) return 'pneu';
  if (/freio/.test(d)) return 'freio';
  if (/revisao/.test(d)) return 'revisao';
  if (/eletrica/.test(d)) return 'eletrica';

  return 'outro';
}

// Detecta tipo de documento
function detectarDocumento(descricao) {
  if (!descricao) return 'outro';

  const d = descricao.toLowerCase();

  if (/ipva/.test(d)) return 'ipva';
  if (/crlv/.test(d)) return 'crlv';
  if (/seguro/.test(d)) return 'seguro';
  if (/cnh/.test(d)) return 'cnh';
  if (/licenci/.test(d)) return 'licenciamento';
  if (/vistoria/.test(d)) return 'vistoria';

  return 'outro';
}

return [{
  json: {
    phone,
    message: parsed.resposta || '',
    intencao: parsed.intencao || 'outro',
    valor: Number(parsed.valor || 0),
    descricao: parsed.descricao || '',
    vencimento: parsed.vencimento || null,

    categoria: detectarCategoria(parsed.descricao),
    tipo_manutencao: detectarTipoManutencao(parsed.descricao),
    tipo_documento: detectarDocumento(parsed.descricao),

    motorista_id: $('HTTP Request1').first().json.id
  }
}];

const pagamentos = $items('HTTP Pagamentos');
const despesas = $items('HTTP Despesas');
const manutencoes = $items('HTTP Manutencao');

const totalReceitas = pagamentos.reduce(
  (acc, item) => acc + Number(item.json.valor || 0),
  0
);

const totalDespesas = despesas.reduce(
  (acc, item) => acc + Number(item.json.valor || 0),
  0
);

const totalManutencoes = manutencoes.reduce(
  (acc, item) => acc + Number(item.json.custo || 0),
  0
);

const lucro = totalReceitas - (totalDespesas + totalManutencoes);

const phone = $('Code in JavaScript').first().json.phone;

return [{
  json: {
    phone,
    message: `📊 Resumo Financeiro

💰 Receitas: R$ ${totalReceitas.toFixed(2)}

💸 Despesas: R$ ${(totalDespesas + totalManutencoes).toFixed(2)}

📈 Lucro: R$ ${lucro.toFixed(2)}`
  }
}];

const passageiros = $('If Vencimento').all();

const pagamentos = $('HTTP Pagamento do mes').all();

const pagantes = new Set(
pagamentos.map(p => p.json.passageiro_id)
);

const inadimplentes = passageiros.filter(
  passageiro => !pagantes.has(passageiro.json.id)
);

return inadimplentes;

const inadimplentes = $input.all();
const motorista = $('Code in JavaScript').first().json;

if (inadimplentes.length === 0 || !inadimplentes[0].json.id) {
  return [{
    json: {
      phone: motorista.phone,
      message: '✅ Boa notícia! Nenhum passageiro está em atraso esse mês. Todos pagaram em dia! 🎉'
    }
  }];
}

let lista = '📋 *Inadimplentes do mês:*\n\n';
inadimplentes.forEach((item, index) => {
  const nome = item.json.passageiros?.nome || 'Desconhecido';
  const valor = Number(item.json.valor_devido).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  const vencimento = new Date(item.json.vencimento).toLocaleDateString('pt-BR');
  lista += `${index + 1}. 👤 ${nome}\n   💰 ${valor} — venceu em ${vencimento}\n\n`;
});

lista += `Total: ${inadimplentes.length} passageiro(s) em atraso.`;

return [{
  json: {
    phone: motorista.phone,
    message: lista
  }
}];

const documentos = $input.all();
const motorista = $('Code in JavaScript').first().json;

if (documentos.length === 0 || !documentos[0].json.id) {
  return [{
    json: {
      phone: motorista.phone,
      message: '📄 Nenhum documento cadastrado ainda. Para cadastrar, me diga: "IPVA vence dia 15/07/2026"'
    }
  }];
}

const hoje = new Date();
hoje.setHours(0, 0, 0, 0);

let mensagem = '📄 *Status dos seus documentos:*\n\n';

documentos.forEach(item => {
  const doc = item.json;
  const vencimento = new Date(doc.vencimento);
  const diasRestantes = Math.ceil((vencimento - hoje) / (1000 * 60 * 60 * 24));

  let icone = '✅';
  let status = '';

  if (diasRestantes < 0) {
    icone = '🚨';
    status = `VENCIDO há ${Math.abs(diasRestantes)} dias!`;
  } else if (diasRestantes <= 7) {
    icone = '🔴';
    status = `vence em ${diasRestantes} dia(s)!`;
  } else if (diasRestantes <= 15) {
    icone = '🟠';
    status = `vence em ${diasRestantes} dias`;
  } else if (diasRestantes <= 30) {
    icone = '🟡';
    status = `vence em ${diasRestantes} dias`;
  } else {
    status = `vence em ${diasRestantes} dias`;
  }

  const dataFormatada = vencimento.toLocaleDateString('pt-BR');
  mensagem += `${icone} *${doc.tipo.toUpperCase()}*\n   📅 ${dataFormatada} — ${status}\n\n`;
});

return [{
  json: {
    phone: motorista.phone,
    message: mensagem
  }
}];
